-- Polské názvy a popisy surovin pro katalog na webu (/pl/suroviny).
-- Přeloženo z českých řádků food_translations; appka sama je nevyrábí,
-- nová surovina v appce spadne na webu na angličtinu (viz src/lib/foods.ts).
-- Idempotentní: řádek se vloží jen tam, kde polský překlad ještě není.

insert into public.food_translations (food_id, locale, name, description)
select v.food_id::uuid, 'pl', v.name, v.description
from (values
  ('29309265-98fe-48df-ab2b-cf366109d04a', $t$Anchois (sardele)$t$, $t$Anchois (sardele) – małe tłuste rybki morskie bogate w omega-3 i wapń (je się w całości). Używaj świeżych/mrożonych, nie solonych. Tłusta ryba morska, cenne źródło omega-3 i witaminy D. Podawaj 1–2× w tygodniu.$t$),
  ('a0000006-0000-0000-0000-000000000003', $t$Banan$t$, $t$Banan – słodki owoc bogaty w potas. Bardzo mała ilość. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('c689b537-46e6-45e2-9afc-a310893e6d7c', $t$Bataty$t$, $t$Bataty – źródło błonnika i beta-karotenu. Podawaj po obróbce termicznej. Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('6051e9b5-863b-4631-8ad4-3e5dda636b4c', $t$Jogurt naturalny$t$, $t$Jogurt naturalny – probiotyki i wapń. Mała ilość. Dodatek mleczny – tylko mała ilość, niektóre psy źle tolerują laktozę. Źródło białka i wapnia.$t$),
  ('a0000006-0000-0000-0000-000000000002', $t$Borówki$t$, $t$Borówki – antyoksydanty, idealny mały przysmak. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('a0000005-0000-0000-0000-000000000002', $t$Brokuł$t$, $t$Brokuł – warzywo kapustne z witaminą C. Tylko mała ilość. Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('fb1b6b73-6cf9-4060-85bc-f747d54d384a', $t$Seler naciowy$t$, $t$Seler naciowy – niskokaloryczne, soczyste warzywo z błonnikiem. Drobno pokroić lub zmiksować (włókniste łodygi). Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('76ebab08-3cc8-4db3-af20-febdb22d4b50', $t$Czarna porzeczka$t$, $t$Czarna porzeczka – ciemne owoce o wyjątkowo wysokiej zawartości witaminy C. Ribes, nie winogrona – w małej ilości bezpieczna. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('6f014bae-e624-452e-a44e-c19e35e86d05', $t$Czerwona porzeczka$t$, $t$Czerwona porzeczka – kwaśne owoce bogate w witaminę C i błonnik. Porzeczka (Ribes) to nie winogrona, dla psów w małej ilości jest bezpieczna. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('a0000005-0000-0000-0000-000000000003', $t$Cukinia$t$, $t$Cukinia – lekkie, dobrze strawne warzywo o niskiej kaloryczności. Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('0c85323f-f4b7-420d-aeee-f5075540d621', $t$Mięso z daniela$t$, $t$Mięso z daniela – chuda dziczyzna. Podstawa dawki – stanowi 50–70 % części mięsnej. Jeśli dziczyzna nie pochodzi ze sprawdzonego źródła (np. z supermarketu), lepiej ją podgotować.$t$),
  ('702a5427-731f-4730-8f64-7efd6289ac10', $t$Dzik$t$, $t$Dzik – ciemne mięso z dziczyzny. Mrożenie ze względu na chorobę Aujeszkyego i włośnie. Podstawa dawki – stanowi 50–70 % części mięsnej. Jeśli dziczyzna nie pochodzi ze sprawdzonego źródła (np. z supermarketu), lepiej ją podgotować.$t$),
  ('16d2ff5e-eadc-4bfd-ad6b-081e7b14cc9a', $t$Dynia$t$, $t$Dynia – delikatny błonnik, wspiera trawienie. Podawaj ugotowaną. Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('19aea7c3-4afb-4e44-9713-577739581ec8', $t$Flaki wołowe$t$, $t$Flaki wołowe – zielony, niemyty żwacz wspiera trawienie i mikrobiom. Żołądek (flaki) – zielony, niemyty świetnie wspiera trawienie i mikrobiom. Liczy się do mięsa mięśniowego.$t$),
  ('a0000004-0000-0000-0000-000000000002', $t$Wątroba wołowa$t$, $t$Wątroba wołowa – klasyczne, najczęstsze źródło wątroby w BARF. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('e1b1a750-4fbf-4aae-9268-48e42b6799b6', $t$Ozór wołowy$t$, $t$Ozór wołowy – tłustsze mięso mięśniowe, liczy się do mięsa. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('a0000003-0000-0000-0000-000000000003', $t$Nerki wołowe$t$, $t$Nerki wołowe – narząd wydzielniczy bogaty w selen i witaminy z grupy B. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('d5b54d70-b04c-4e41-b3f8-e6cf43a8b0a8', $t$Policzki wołowe$t$, $t$Policzki wołowe – mięsień pracujący, chude i soczyste. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('dfe72b7d-72a0-46b2-a91e-9363997b2a49', $t$Kość szpikowa wołowa$t$, $t$Kość szpikowa wołowa – bardzo twarda kość nośna, tylko do gryzienia. Twardsza kość nośna – raczej rekreacyjnie do gryzienia niż do zjedzenia. ZAWSZE surowa, pilnuj ścierania zębów.$t$),
  ('1395dd80-e114-4772-af5b-27900c91b465', $t$Mózg wołowy$t$, $t$Mózg wołowy – źródło zdrowych tłuszczów i DHA. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('f3249739-7cd5-4a86-a39d-f724e019a0e6', $t$Ogon wołowy$t$, $t$Ogon wołowy – mięsista kość z chrząstką, źródło kolagenu. Twardsza kość nośna – raczej rekreacyjnie do gryzienia niż do zjedzenia. ZAWSZE surowa, pilnuj ścierania zębów.$t$),
  ('a0000003-0000-0000-0000-000000000004', $t$Płuca wołowe$t$, $t$Płuca wołowe – lekki, niskotłuszczowy narząd. Podawaj jako uzupełnienie części mięsnej, popularny też suszony jako przysmak.$t$),
  ('aaf196f4-c2ea-4251-bf7a-a286ed463234', $t$Tchawica wołowa$t$, $t$Tchawica wołowa – chrząstka z glukozaminą, świetny gryzak. Część chrzęstna – naturalne źródło glukozaminy i chondroityny dla stawów. Popularny gryzak.$t$),
  ('9acb18fb-345e-4b90-9dfa-1572ee0d4c80', $t$Śledziona wołowa$t$, $t$Śledziona wołowa – narząd wydzielniczy bardzo bogaty w żelazo. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('3f9c2160-688e-4799-8c46-e968d7098af8', $t$Trzustka wołowa$t$, $t$Trzustka wołowa – narząd wydzielniczy, naturalne enzymy (odpowiednia przy EPI). Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('a0000003-0000-0000-0000-000000000002', $t$Serce wołowe$t$, $t$Serce wołowe – doskonałe źródło tauryny, przystępne cenowo. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('a0000001-0000-0000-0000-000000000002', $t$Mięso mięśniowe wołowe$t$, $t$Mięso mięśniowe wołowe – podstawowe chude mięso dawki BARF. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('56778459-2e46-48e7-bc0b-9c66363f028a', $t$Wymię wołowe$t$, $t$Wymię wołowe – tłuste uzupełniające mięso mięśniowe. Liczy się do mięsa mięśniowego, nie do podrobów – nie ma witaminy A, miedzi ani selenu jak wątroba czy nerki. Mało białka i dużo tłuszczu, więc tylko dla urozmaicenia – wołowiny nie zastąpi.$t$),
  ('45ce601b-9401-40c7-bbce-cd0e0be3e84e', $t$Gruszka$t$, $t$Gruszka – soczysty owoc z błonnikiem. Bez gniazda nasiennego. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('adfbf92d-ab6a-4667-8bbb-c4f11c9456d1', $t$Wątroba gęsia$t$, $t$Wątroba gęsia – tłusta i bogata, tylko w małej ilości. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('50cd76c8-593c-4209-adf0-288ddacdc443', $t$Szyje gęsie$t$, $t$Szyje gęsie – tłustsza duża kość jadalna. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('1ac34fa5-d58e-4174-8e68-4d60bd04719a', $t$Mięso gęsie$t$, $t$Mięso gęsie – tłustszy drób, bogaty smak. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('a0000006-0000-0000-0000-000000000001', $t$Jabłko$t$, $t$Jabłko – źródło błonnika i witaminy C. Usuń gniazdo nasienne (pestki zawierają cyjanek). Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('2bf512d2-fe48-40b4-a185-3148bbf4b741', $t$Truskawki$t$, $t$Truskawki – witamina C i błonnik, jako przysmak. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('7164342c-b939-45eb-b9aa-871d02c062e8', $t$Wątroba jagnięca$t$, $t$Wątroba jagnięca – bogata w miedź i witaminę A. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('d35ddd87-a7b9-43cf-9455-3ab48b9c9ee6', $t$Ozór jagnięcy$t$, $t$Ozór jagnięcy – tłustsze mięso mięśniowe. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('ee19cd47-c739-4e64-a446-b33795e3d842', $t$Nerki jagnięce$t$, $t$Nerki jagnięce – mniejsze, delikatniejsze nerki. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('a0000001-0000-0000-0000-000000000004', $t$Mięso jagnięce$t$, $t$Mięso jagnięce – tłustsze czerwone mięso o wyrazistym smaku. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('07e8641d-d73b-44d1-b437-057fbde6e71b', $t$Płuca jagnięce$t$, $t$Płuca jagnięce – lekki narząd, popularny suszony przysmak. Lekki, niskotłuszczowy narząd. Podawaj jako uzupełnienie części mięsnej, popularny też suszony jako przysmak.$t$),
  ('f925dca9-49b2-4c90-a1a9-ed4fb158c7bd', $t$Serce jagnięce$t$, $t$Serce jagnięce – mniejsze serce, idealne dla średnich psów. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('3c87d0ca-fee4-45ac-853a-bc90a308dcef', $t$Żeberka jagnięce$t$, $t$Żeberka jagnięce – kość jadalna z warstwą mięsa i tłuszczu. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('fc9b60eb-dc25-43c2-bae7-6e5502792888', $t$Wątroba jelenia$t$, $t$Wątroba jelenia – wątroba z dziczyzny, bogata w składniki odżywcze. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('ed329b3b-fb4e-41cb-b303-1da314174fc4', $t$Wątroba kacza$t$, $t$Wątroba kacza – tłustsza wątroba drobiowa. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('c74f3c78-af49-48a4-9eee-590b7eacc587', $t$Skrzydła kacze$t$, $t$Skrzydła kacze – mięsista kość jadalna. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000002-0000-0000-0000-000000000003', $t$Szyje kacze$t$, $t$Szyje kacze – większa kość jadalna dla średnich i dużych psów. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000001-0000-0000-0000-000000000005', $t$Pierś kacza$t$, $t$Pierś kacza – chudsze ciemne mięso drobiowe. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('a4f6cd41-cea7-4fa5-adfc-3b11c0b64dc0', $t$Korpusy kacze$t$, $t$Korpusy kacze – tłustszy szkielet z chrząstką. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('2e3cc505-ceb6-4c91-87c7-efbaba617d87', $t$Serca kacze$t$, $t$Serca kacze – mały narząd mięśniowy z tauryną. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('53361084-adb1-43de-8ac2-ac73025ccd1c', $t$Żołądki kacze$t$, $t$Żołądki kacze – mięsiste i smaczne. Mięśniowy żołądek, liczy się do mięsa mięśniowego. Naturalnie bogaty w białko.$t$),
  ('8a817089-1223-4042-8ea3-e01e0e265b78', $t$Wątroba końska$t$, $t$Wątroba końska – chuda i bogata w żelazo. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('e36871a2-7e20-4c68-90d9-0df96ec31118', $t$Mięso końskie$t$, $t$Mięso końskie – chude, hipoalergiczne, odpowiednie przy alergiach. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('f81d67a3-a49e-49f3-af72-27ee577c3ed0', $t$Serce końskie$t$, $t$Serce końskie – chudy narząd mięśniowy. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('1f48fd0f-78a3-4091-8c7b-49e39bc39c3c', $t$Mięso kozie$t$, $t$Mięso kozie – chude czerwone mięso, mało alergizujące. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('0236d8aa-8504-4618-94ea-a37b83a6a572', $t$Wątroba królicza$t$, $t$Wątroba królicza – chuda wątroba z chudego mięsa. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('1ef4deb1-21c7-44a0-9215-8d6350bf5d6b', $t$Mięso królicze$t$, $t$Mięso królicze – chude i lekkostrawne, hipoalergiczne. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('53081f21-372e-44e9-87bb-d933f5f475e1', $t$Królik w całości (z kością)$t$, $t$Cały królik z kością – kompletna zdobycz: mięso mięśniowe, jadalne kości i podroby razem. Aplikacja rozlicza go w przybliżeniu na 60 % mięsa mięśniowego, 30 % kości i 10 % podrobów. ZAWSZE na surowo, nigdy gotowany (gotowane kości pękają na ostre odłamki).$t$),
  ('dc010526-9f58-49cb-8ff1-adb082496379', $t$Przepiórka (cała)$t$, $t$Cała przepiórka – kompletna mała zdobycz razem z kośćmi i narządami. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('20e99202-683d-4dce-97ce-7e29b616f3e1', $t$Wątroba indycza$t$, $t$Wątroba indycza – drobiowe źródło wątroby. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('68f7535a-d943-4647-92b2-ae4116ca009f', $t$Skrzydła indycze$t$, $t$Skrzydła indycze – mięsista kość jadalna dla większych psów. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('c4e9cc16-dd6a-4fef-b83e-2bcf2a6cf127', $t$Szyje indycze$t$, $t$Szyje indycze – duża kość jadalna dla dużych psów. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000001-0000-0000-0000-000000000003', $t$Pierś indycza$t$, $t$Pierś indycza – bardzo chude białe mięso. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('c416d378-17da-493a-a961-4346c65ca704', $t$Serce indycze$t$, $t$Serce indycze – narząd mięśniowy bogaty w taurynę. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('45c82f5d-99ad-4f15-b714-2ba229bf308d', $t$Udo indycze$t$, $t$Udo indycze – ciemniejsze, nieco tłustsze mięso. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('8c2ad4ff-590b-49d4-ad24-00c4ddf6425c', $t$Żołądki indycze$t$, $t$Żołądki indycze – mięsisty narząd, do mięsa mięśniowego. Mięśniowy żołądek, liczy się do mięsa mięśniowego. Naturalnie bogaty w białko.$t$),
  ('a0000002-0000-0000-0000-000000000002', $t$Grzbiety kurze$t$, $t$Grzbiety kurze z chrząstką i resztkami mięsa. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000004-0000-0000-0000-000000000001', $t$Wątroba kurza$t$, $t$Wątroba kurza – miękka i łatwo dostępna, odpowiednia dla małych psów. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('6fa17f82-6bfe-4071-b9ff-eaf134ded315', $t$Skrzydła kurze$t$, $t$Skrzydła kurze – dobrze strawna kość jadalna. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000002-0000-0000-0000-000000000001', $t$Szyje kurze$t$, $t$Miękkie szyje kurze, idealna kość jadalna dla małych i średnich psów. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('e7d8fcb4-ae47-46c1-89ec-f4324a565e4c', $t$Łapki kurze$t$, $t$Łapki kurze – naturalne źródło glukozaminy, popularny przysmak. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000001-0000-0000-0000-000000000001', $t$Pierś z kurczaka$t$, $t$Pierś z kurczaka – chude białe mięso, podstawa dla wrażliwych psów. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('8086894d-8fb1-4590-bcf2-a88b9cede648', $t$Korpusy kurze$t$, $t$Korpusy kurze (szkielety) po wykostowaniu, z chrząstką i resztkami mięsa. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('a0000003-0000-0000-0000-000000000001', $t$Serca kurze$t$, $t$Serca kurze – małe serduszka, popularne źródło tauryny. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('a4b3be39-3cc1-4583-8cd7-7610b627ef70', $t$Udo z kurczaka$t$, $t$Udo z kurczaka – ciemniejsze, soczyste mięso. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('a824dddb-fd60-4bb3-870c-c2f9501de3ad', $t$Żołądki kurze$t$, $t$Żołądki kurze – mięsiste, liczą się do mięsa mięśniowego. Mięśniowy żołądek, liczy się do mięsa mięśniowego. Naturalnie bogaty w białko.$t$),
  ('7f31950d-8120-4e40-a229-5937b1731d79', $t$Kalafior$t$, $t$Kalafior – warzywo kapustne z witaminą C i folianami. Najlepiej lekko podgotować na parze. Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('b6e5ab5e-544b-4e68-9490-0d1c1c79bee5', $t$Łosoś$t$, $t$Łosoś – tłusta ryba bogata w omega-3. Mrożony min. 3 tygodnie ze względu na pasożyty. Tłusta ryba morska, cenne źródło omega-3 i witaminy D. Podawaj 1–2× w tygodniu.$t$),
  ('a0000007-0000-0000-0000-000000000001', $t$Olej z łososia$t$, $t$Olej z łososia – płynne źródło omega-3 dla sierści i stawów. Dodatek kwasów omega-3 dla sierści i stawów. Od kilku kropli do ml dziennie w zależności od wielkości psa.$t$),
  ('0ebe106b-b2c4-4273-937a-3f34bdd94f3b', $t$Makrela$t$, $t$Makrela – tłusta ryba morska z omega-3. Tłusta ryba morska, cenne źródło omega-3 i witaminy D. Podawaj 1–2× w tygodniu.$t$),
  ('0943f697-a6db-4de0-baf6-62df039a0328', $t$Maliny$t$, $t$Maliny – owoce bogate w błonnik i witaminę C. Tylko mała ilość (zawierają śladowe ilości ksylitolu). Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('4d946245-2f63-4a2b-876b-53c526b7384b', $t$Mielone skorupki jaj$t$, $t$Mielone skorupki jaj – czysty wapń do dawek bez kości. Dodatek wapnia do dawek bez kości. Ok. 1 g (½ łyżeczki) na 500 g mięsa.$t$),
  ('5d14b3ac-b118-4cb2-8a3a-0625ee499265', $t$Algi morskie$t$, $t$Algi morskie – naturalne źródło jodu. Tylko szczypta. Naturalne źródło jodu dla tarczycy. Tylko szczypta – łatwo przedawkować jod.$t$),
  ('a0000005-0000-0000-0000-000000000001', $t$Marchew$t$, $t$Marchew – beta-karoten i błonnik, lubiana też na surowo do gryzienia. Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('1dc17ceb-c3cb-4328-af14-51131bc06525', $t$Jeżyny$t$, $t$Jeżyny – ciemne owoce z antyoksydantami i błonnikiem. Idealny mały przysmak. Owoce tylko jako okazjonalny przysmak w małej ilości ze względu na zawartość cukru.$t$),
  ('b2f1e6a4-7c3d-4b8e-9a12-5f7c9d0e1a23', $t$Por$t$, $t$Por – warzywo z rodzaju Allium. UWAGA: por jest dla psów toksyczny (tak samo jak cebula i czosnek) – uszkadza czerwone krwinki i może wywołać anemię hemolityczną. Niezalecany do karmienia, nawet po obróbce termicznej.$t$),
  ('c815843e-9614-4cb4-bd19-df93b3f0726d', $t$Algi nori$t$, $t$Algi nori – wodorosty z jodem i witaminą A, łagodniejsze niż kelp. Podawaj tylko małą ilość. Naturalne źródło jodu dla tarczycy. Tylko mała ilość – łatwo przedawkować jod.$t$),
  ('b1668561-d079-4ee0-a6b7-df9ccf3286dd', $t$Sardynki$t$, $t$Sardynki – małe ryby morskie, w całości razem z ośćmi. Tłusta ryba morska, cenne źródło omega-3 i witaminy D. Podawaj 1–2× w tygodniu.$t$),
  ('d3c9da3b-e70e-42f7-b815-f019d1d97461', $t$Śledź$t$, $t$Śledź – tłusta ryba morska, źródło omega-3 i witaminy D. Tłusta ryba morska, cenne źródło omega-3 i witaminy D. Podawaj 1–2× w tygodniu.$t$),
  ('a0000005-0000-0000-0000-000000000004', $t$Szpinak$t$, $t$Szpinak – warzywo liściaste bogate w żelazo. Z umiarem (szczawiany). Warzywa – ok. 10 % dawki. Dla lepszej strawności zmiksować lub lekko podgotować na parze.$t$),
  ('8c40218d-0b9e-49c5-b376-34b3dd3e58bf', $t$Mięso z sarny$t$, $t$Mięso z sarny – delikatna chuda dziczyzna. Podstawa dawki – stanowi 50–70 % części mięsnej. Jeśli dziczyzna nie pochodzi ze sprawdzonego źródła (np. z supermarketu), lepiej ją podgotować.$t$),
  ('4258ea8a-cbdb-4349-9b8b-c5714717f8f0', $t$Wątroba cielęca$t$, $t$Wątroba cielęca – delikatniejsza i lżejsza niż wołowa. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('f1085f36-49e8-4bf6-93e6-206687616f05', $t$Mięso mięśniowe cielęce$t$, $t$Mięso mięśniowe cielęce – delikatne chude mięso. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('17da90b5-de38-41bd-bbe7-e0a4efb2ec67', $t$Twaróg$t$, $t$Twaróg – lekkie białko i wapń. Dodatek mleczny – tylko mała ilość, niektóre psy źle tolerują laktozę. Źródło białka i wapnia.$t$),
  ('a0000007-0000-0000-0000-000000000002', $t$Jajko$t$, $t$Jajko – pełnowartościowe białko; ze skorupką także źródło wapnia. Całe jajko ze skorupką – pełnowartościowe białko i wapń. 2–3× w tygodniu w zależności od wielkości psa.$t$),
  ('6dff6fc2-dfdd-40cb-9de2-4ac3864885c3', $t$Przepona wieprzowa$t$, $t$Przepona wieprzowa – cienki mięsień przepony, smaczne mięso mięśniowe. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('bb8a8f3d-c79d-4ee3-a03b-40943c8e46bb', $t$Głowa wieprzowa$t$, $t$Głowa wieprzowa – mięso, chrząstka i kość razem. Twardsza kość nośna – raczej rekreacyjnie do gryzienia niż do zjedzenia. ZAWSZE surowa, pilnuj ścierania zębów.$t$),
  ('5cfdf04b-cfba-4cd7-b52e-0dcb6a3844f1', $t$Wątroba wieprzowa$t$, $t$Wątroba wieprzowa – dostępne źródło wątroby, wyrazisty smak. Najważniejszy narząd w BARF, wyjątkowo bogaty w witaminę A, miedź i żelazo. Maks. 5 % dawki, inaczej grozi przedawkowanie witaminy A.$t$),
  ('af918a13-86cd-4a50-bac8-88b550b4a5a9', $t$Karkówka wieprzowa$t$, $t$Karkówka wieprzowa – bardziej soczysty, przerośnięty element. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('835bf3b4-0ed7-41f5-a780-0acaef4c3590', $t$Szynka wieprzowa$t$, $t$Szynka wieprzowa – chudszy tylny element. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('59676165-74e0-4e97-993e-2ce4aa470717', $t$Policzki wieprzowe$t$, $t$Policzki wieprzowe – soczysty mięsień pracujący. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('80f5f491-4091-4b6f-8a93-b30db86cc90a', $t$Kość szpikowa wieprzowa$t$, $t$Kość szpikowa wieprzowa – twarda kość nośna, rekreacyjnie do gryzienia. Twardsza kość nośna – raczej rekreacyjnie do gryzienia niż do zjedzenia. ZAWSZE surowa, pilnuj ścierania zębów.$t$),
  ('754de29a-cd26-406f-86cd-2c5a82d8ea5d', $t$Polędwiczka wieprzowa$t$, $t$Polędwiczka wieprzowa – najchudszy element wieprzowiny. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('0e056f3b-1cb6-4453-bf8d-1e6029246a46', $t$Schab wieprzowy (kotlet)$t$, $t$Schab wieprzowy (kotlet) – chude mięso z grzbietu. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('c6d2374c-71f7-4f34-a816-f259c96e7448', $t$Łopatka wieprzowa$t$, $t$Łopatka wieprzowa – średnio tłusty element. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('1588c11d-3a4d-4ee7-bdb8-13999488b15c', $t$Śledziona wieprzowa$t$, $t$Śledziona wieprzowa – narząd bogaty w żelazo. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('381853bc-32bc-4e3c-842c-f588fd652fd7', $t$Trzustka wieprzowa$t$, $t$Trzustka wieprzowa – źródło enzymów trawiennych. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('d5b2b7e3-34e8-4846-812b-da1ea3131e01', $t$Mięso mięśniowe wieprzowe$t$, $t$Mięso mięśniowe wieprzowe – wieprzowina ogólnie. Zawsze dobrze zamrożona (Aujeszky). Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('cc786e81-634e-4aba-acf1-de134cd83850', $t$Żeberka wieprzowe$t$, $t$Żeberka wieprzowe – mięsista kość jadalna. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('4224fc51-d21a-4c08-ad09-2e20d29f6bec', $t$Golonka wieprzowa$t$, $t$Golonka wieprzowa – twardsza kość nośna z mięsem. Twardsza kość nośna – raczej rekreacyjnie do gryzienia niż do zjedzenia. ZAWSZE surowa, pilnuj ścierania zębów.$t$),
  ('876caa4e-47a0-4ac0-b524-2f5d72aacb97', $t$Nerki wieprzowe$t$, $t$Nerki wieprzowe – dostępny narząd wydzielniczy. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('01ffd839-64be-4c08-b7e6-05e49bbc9961', $t$Nóżki wieprzowe$t$, $t$Nóżki wieprzowe – skóra, chrząstka i kość, źródło kolagenu. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('79930f0f-64d7-4f43-a080-8b0f7e2dbd8f', $t$Płuca wieprzowe$t$, $t$Płuca wieprzowe – lekki, niskotłuszczowy narząd. Podawaj jako uzupełnienie części mięsnej, popularny też suszony jako przysmak.$t$),
  ('ef60c485-97b6-4285-b971-92663e5dfd57', $t$Smalec wieprzowy$t$, $t$Smalec wieprzowy – czysty tłuszcz zwierzęcy, skoncentrowana energia. Czysty tłuszcz – skoncentrowane źródło energii. Używaj z umiarem, głównie u psów aktywnych lub niedożywionych.$t$),
  ('b5129d74-6082-416d-a926-d3512ebd7381', $t$Serce wieprzowe$t$, $t$Serce wieprzowe – narząd mięśniowy z tauryną. Narząd mięśniowy bogaty w taurynę – liczy się do mięsa mięśniowego, nie do podrobów. Do 10–15 % dawki.$t$),
  ('4746ff20-9eb2-49c5-a856-bf10ed381957', $t$Uszy wieprzowe$t$, $t$Uszy wieprzowe – chrzęstny przysmak do gryzienia. Część chrzęstna – naturalne źródło glukozaminy i chondroityny dla stawów. Popularny gryzak.$t$),
  ('b50e8776-88e4-41b9-b0bd-8898b0de24a7', $t$Grasica wieprzowa$t$, $t$Grasica wieprzowa – gruczołowy narząd wydzielniczy o delikatnym smaku. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('3b5e40a9-b3d2-438d-b49f-bb8bede65120', $t$Boczek wieprzowy$t$, $t$Boczek wieprzowy – bardzo tłusty, energetyczny element. Z umiarem. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('6c21434d-854d-405e-831b-54fe8eb33d95', $t$Ozór wieprzowy$t$, $t$Ozór wieprzowy – tłustsze mięso mięśniowe. Podstawa dawki – stanowi 50–70 % części mięsnej.$t$),
  ('e7b543db-0607-4c85-b4a5-eb47289b8784', $t$Mózg wieprzowy$t$, $t$Mózg wieprzowy – bogaty w tłuszcze i DHA. Narząd wydzielniczy (podroby). Razem z wątrobą stanowi ok. 10 % dawki, z czego narządy inne niż wątroba ~5 %.$t$),
  ('c3268866-3fc0-45ad-86d3-546ad12c8d3f', $t$Ogonek wieprzowy$t$, $t$Ogonek wieprzowy – tłusta kość jadalna z chrząstką. Jadalna miękka kość – źródło wapnia. Stanowi ok. 10–15 % dawki. ZAWSZE na surowo, nigdy gotowana (gotowane kości pękają na ostre odłamki).$t$),
  ('6e8b6695-b121-4fa1-b17e-9fce79b614d1', $t$Żołądek wieprzowy$t$, $t$Żołądek wieprzowy – mięsisty narząd, wspiera trawienie. Żołądek (flaki) – zielony, niemyty świetnie wspiera trawienie i mikrobiom. Liczy się do mięsa mięśniowego.$t$),
  ('914c4da0-4e64-4384-b334-59fdbf8516db', $t$Dziczyzna (jeleń)$t$, $t$Dziczyzna (jeleń) – chude ciemne mięso. Podstawa dawki – stanowi 50–70 % części mięsnej. Jeśli dziczyzna nie pochodzi ze sprawdzonego źródła (np. z supermarketu), lepiej ją podgotować.$t$)
) as v(food_id, name, description)
where not exists (
  select 1 from public.food_translations t where t.food_id = v.food_id::uuid and t.locale = 'pl'
);
